using System;using System.Data;using TNS.KYM;using TNS.TMM.IsKurallari.Veri;using TNS.Veri;namespace TNS.TMM.IsKurallari{    /// <summary>    /// Sayım formu bilgileriyle ilgili, iş kuralları kontrollerini yapıp,    /// veri tabanı bağlantısını alıp, veri tabanı fonksiyonlarını çağırarak    /// okuma, yazma işlemlerini gerçekleştiren fonksiyonları tutan sınıf    /// </summary>    public class TMMSayimForm    {        /// <summary>        /// Parametre olarak verilen sayım formu bilgilerinin doğruluğunu kontrol eden yordam        /// </summary>        /// <param name="kullanan">İşlemi yapan kullanıcıya ait bilgileri tutan nesne</param>        /// <param name="sf">Sayım formu bilgilerini tutan nesne</param>        /// <returns>İşlemin sonucunun başarılı olup olmadığı ve başarılı değilse sebebi Sonuc yapısında döndürülür.</returns>        private static Sonuc Kontrol(Kullanici kullanan, SayimForm sf)        {            Sonuc sonuc = new Sonuc();            if (sf.yil == 0)                sonuc.hataStr += TasinirMalResI.TMM036 + "<br>";            if (sf.muhasebeKod == string.Empty)                sonuc.hataStr += TasinirMalResI.TMM013 + "<br>";            if (sf.harcamaKod == string.Empty)                sonuc.hataStr += TasinirMalResI.TMM014 + "<br>";            if (sf.ambarKod == string.Empty)                sonuc.hataStr += TasinirMalResI.TMM031 + "<br>";            if (sf.sayimTarih.isNull)                sonuc.hataStr += TasinirMalResI.TMM197 + "<br>";            sonuc.hataStr += Genel.KontrolMuhasebeHarcamaAmbar(sf.muhasebeKod, sf.harcamaKod, sf.ambarKod);            //Detay kontrol            if (sf.detay.Count < 1)                sonuc.hataStr += TasinirMalResI.TMM198 + "<br>";            else            {                int satir = 1;                foreach (SayimDetay sd in sf.detay)                {                    sonuc.hataStr += Genel.KontrolHesapPlan(kullanan, sd.hesapPlanKod, satir, false, true);                    satir++;                }            }            if (sonuc.hataStr != String.Empty)                sonuc.islemSonuc = false;            return sonuc;        }        /// <summary>        /// Sayım tutanağı formunu varsa güncelleyen, yoksa kaydeden yordam        /// Sayım tutanağı formu ve detay bilgileri ile ilgili bir takım kontroller yapılmakta,        /// sorunsuz bir bilgi kümesi olduğuna karar verilirse kayıt işlemi yapılmaktadır.        /// Kullanıcı işleme yetkili değilse veya gönderilen SayimForm nesnesi eksikse işlemi yapmaz ve hata döndürür.        /// </summary>        /// <param name="veriErisim">Veri tabanı bağlantı nesnesi</param>        /// <param name="kullanan">İşlemi yapan kullanıcıya ait bilgileri tutan nesne</param>        /// <param name="sf">Sayım tutanağı formunun bilgilerini tutan nesne</param>        /// <returns>İşlemin sonucunun başarılı olup olmadığı ve başarılı değilse sebebi Sonuc yapısında döndürülür.</returns>        public static Sonuc Kaydet(VeriErisim veriErisim, Kullanici kullanan, SayimForm sf)        {            Sonuc sonuc = new Sonuc();            sonuc.islemSonuc = TMMYetkiKontrol.YazmaYetkisiVarMi(kullanan, sf.muhasebeKod, sf.harcamaKod, sf.ambarKod);            if (!sonuc.islemSonuc)            {                sonuc.hataStr = TasinirMalResI.TMM050;                return sonuc;            }            sonuc = Kontrol(kullanan, sf);            if (sonuc.hataStr != String.Empty)                return sonuc;            VeriErisim ve = VeriErisim.VeriErisimBul(veriErisim, "BaglantiSatiriTMM", TNS.KYM.Arac.KimlikBul(kullanan));            TABSayimForm tabSayimForm = new TABSayimForm(ve);            TABSayimDetay tabSayimDetay = new TABSayimDetay(ve);            ve.BeginTransaction();            if (sf.sayimNo.Trim() == string.Empty)                sonuc = tabSayimForm.Kaydet(sf);            else                sonuc = tabSayimForm.Guncelle(sf);            //Sayım belge numarası sayaçtan değil formun maxından alınıyor            sf.sayimNo = sonuc.anahtar;            if (!sonuc.islemSonuc)            {                ve.Rollback();                ve.VeriErisimKapat();                return sonuc;            }            sonuc = tabSayimDetay.Sil(sf);            if (!sonuc.islemSonuc)            {                ve.Rollback();                ve.VeriErisimKapat();                return sonuc;            }
            //Gönderilen sayım form detayında aynı hesap kodunda birden fazla satır var ise 
            //tek satıra indirmek için
            for (int k = 0; k < sf.detay.Count; k++)            {                SayimDetay detay1 = (SayimDetay)sf.detay[k];                for (int j = k + 1; j < sf.detay.Count; j++)                {                    SayimDetay detay2 = (SayimDetay)sf.detay[j];                    if (detay1.hesapPlanKod.Replace(".", "") == detay2.hesapPlanKod.Replace(".", ""))                    {                        detay1.ambarMiktar += detay2.ambarMiktar;                        detay1.ortakMiktar += detay2.ortakMiktar;                        detay1.aciklama += " " + detay2.aciklama;                        sf.detay.Remove(detay2);                        j--;//Remove edilen kayıttan sonraki gelen yerini aldığı için kontrol edilemiyordu                    }                }            }            foreach (SayimDetay sd in sf.detay)            {                sd.sayimNo = sf.sayimNo;                sonuc = tabSayimDetay.Kaydet(sd);                if (!sonuc.islemSonuc)                {                    ve.Rollback();                    ve.VeriErisimKapat();                    return sonuc;                }            }            if (sonuc.islemSonuc)            {                sonuc.anahtar = sf.sayimNo;                sonuc.bilgiStr = TasinirMalResI.TMM017;                ve.Commit();            }            else            {                sonuc.hataStr = TasinirMalResI.TMM200 + "<br>" + sonuc.hataStr;                ve.Rollback();            }            ve.VeriErisimKapat();            return sonuc;        }        /// <summary>        /// Parametre olarak verilen sayım tutanağı formunu ve detayını silen yordam        /// Kullanıcı işleme yetkili değilse veya gönderilen SayimForm nesnesi eksikse işlemi yapmaz ve hata döndürür.        /// </summary>        /// <param name="veriErisim">Veri tabanı bağlantı nesnesi</param>        /// <param name="kullanan">İşlemi yapan kullanıcıya ait bilgileri tutan nesne</param>        /// <param name="sf">Sayım tutanağı formunun bilgilerini tutan nesne</param>        /// <returns>İşlemin sonucunun başarılı olup olmadığı ve başarılı değilse sebebi Sonuc yapısında döndürülür.</returns>        public static Sonuc Sil(VeriErisim veriErisim, Kullanici kullanan, SayimForm sf)        {            Sonuc sonuc = new Sonuc();            sonuc.islemSonuc = TMMYetkiKontrol.YazmaYetkisiVarMi(kullanan, sf.muhasebeKod, sf.harcamaKod, sf.ambarKod);            if (!sonuc.islemSonuc)            {                sonuc.hataStr = TasinirMalResI.TMM050;                return sonuc;            }            VeriErisim ve = VeriErisim.VeriErisimBul(veriErisim, "BaglantiSatiriTMM", TNS.KYM.Arac.KimlikBul(kullanan));            TABSayimForm tabSayimForm = new TABSayimForm(ve);            TABSayimDetay tabSayimDetay = new TABSayimDetay(ve);            ve.BeginTransaction();            sonuc = tabSayimDetay.Sil(sf);            if (sonuc.islemSonuc)                sonuc = tabSayimForm.Sil(sf);            if (sonuc.islemSonuc)            {                sonuc.bilgiStr = TasinirMalResI.TMM162 + "</b>";                ve.Commit();            }            else            {                sonuc.hataStr = TasinirMalResI.TMM163 + "<br>" + sonuc.hataStr;                ve.Rollback();            }            ve.VeriErisimKapat();            return sonuc;        }        /// <summary>        /// Verilen kriterlere uygun olan sayım tutanağı formlarını döndüren yordam        /// Kullanıcı işleme yetkili değilse veya gönderilen SayimForm nesnesi eksikse işlemi yapmaz ve hata döndürür.        /// </summary>        /// <param name="veriErisim">Veri tabanı bağlantı nesnesi</param>        /// <param name="kullanan">İşlemi yapan kullanıcıya ait bilgileri tutan nesne</param>        /// <param name="sf">Sayım tutanağı formu bilgilerini tutan nesne</param>        /// <param name="detayVer">Sayım tutanağı formlarının detay bilgilerinin istenip istenmediği bilgisi</param>        /// <param name="kayitBilgiEkle">Kayıtlara göre miktar bilgilerinin istenip istenmediği bilgisi</param>        /// <returns>Hata varsa ObjectArray içindeki Sonuc yapısında hata döndürülür, yoksa TNSCollection yapısında sayım tutanağı formları listesi döndürülür.</returns>        public static ObjectArray Listele(VeriErisim veriErisim, Kullanici kullanan, SayimForm sf, bool detayVer, bool kayitBilgiEkle)        {            ObjectArray donusDeger = new ObjectArray();            if (sf.yil == 0)            {                donusDeger.sonuc.hataStr += TasinirMalResI.TMM036 + "<br>";                donusDeger.sonuc.islemSonuc = false;                return donusDeger;            }            if (!kullanan.KullaniciTipiIceriyorMu((int)ENUMKullaniciTipi.SISTEMYONETICISI))            {                donusDeger.sonuc.islemSonuc = TMMYetkiKontrol.GormeYetkisiVarMi(kullanan, sf.muhasebeKod, sf.harcamaKod, sf.ambarKod);                if (!donusDeger.sonuc.islemSonuc)                {                    donusDeger.sonuc.hataStr = TasinirMalResI.TMM060;                    return donusDeger;                }            }            if (string.IsNullOrEmpty(sf.muhasebeKod))                donusDeger.sonuc.hataStr += TasinirMalResI.TMM142 + "<br>";            if (string.IsNullOrEmpty(sf.harcamaKod))                donusDeger.sonuc.hataStr += TasinirMalResI.TMM014 + "<br>";            if (string.IsNullOrEmpty(sf.ambarKod))                donusDeger.sonuc.hataStr += TasinirMalResI.TMM031 + "<br>";            if (!string.IsNullOrEmpty(donusDeger.sonuc.hataStr))            {                donusDeger.sonuc.islemSonuc = false;                return donusDeger;            }            VeriErisim ve = VeriErisim.VeriErisimBul(veriErisim, "BaglantiSatiriTMM", TNS.KYM.Arac.KimlikBul(kullanan));            VeriErisim ve2 = VeriErisim.VeriErisimBul(veriErisim, "BaglantiSatiriTMM", TNS.KYM.Arac.KimlikBul(kullanan));            TABSayimForm tabSF = new TABSayimForm(ve);            IDataReader dr = null;            try            {                dr = tabSF.Listele(sf);            }            catch (Exception e)            {                donusDeger.sonuc.islemSonuc = false;                donusDeger.sonuc.hataStr = e.Message;                dr.Close();                ve.VeriErisimKapat();                ve2.VeriErisimKapat();                return donusDeger;            }            System.Collections.Hashtable isimler = new System.Collections.Hashtable();            while (dr.Read())            {                SayimForm gelen = new SayimForm();                gelen.yil = VeriErisim.DegerAl(dr, 0, 0);                gelen.muhasebeKod = VeriErisim.DegerAl(dr, 1, string.Empty);                gelen.muhasebeAd = Genel.AdGetir(isimler, gelen.muhasebeKod, "TASMUHASEBE");                gelen.harcamaKod = VeriErisim.DegerAl(dr, 2, string.Empty);                gelen.harcamaKod = OrtakFonksiyonlar.KodNoktaKoy(Genel.KodYapiDondur(false), gelen.harcamaKod);                gelen.harcamaAd = Genel.AdGetir(isimler, gelen.muhasebeKod + "-" + gelen.harcamaKod, "TASHARCAMABIRIM");                gelen.ambarKod = VeriErisim.DegerAl(dr, 3, string.Empty);                gelen.ambarAd = Genel.AdGetir(isimler, gelen.muhasebeKod + "-" + gelen.harcamaKod + "-" + gelen.ambarKod, "TASAMBAR");                gelen.sayimNo = VeriErisim.DegerAl(dr, 4, string.Empty);                gelen.sayimTarih = VeriErisim.DegerAl(dr, 5);                gelen.ilKod = VeriErisim.DegerAl(dr, 6, string.Empty);                gelen.ilAd = VeriErisim.DegerAl(dr, 7, string.Empty);                gelen.ilceKod = VeriErisim.DegerAl(dr, 8, string.Empty);                gelen.ilceAd = VeriErisim.DegerAl(dr, 9, string.Empty);                //Detayları listele                if (detayVer)                {                    ObjectArray detayBilgi = DetayListele(ve2, kullanan, gelen, kayitBilgiEkle);                    if (!detayBilgi.sonuc.islemSonuc)                    {                        donusDeger.sonuc = detayBilgi.sonuc;                        break;                    }                    gelen.detay = detayBilgi.objeler;                }                donusDeger.objeler.Add(gelen);            }            if (donusDeger.sonuc.islemSonuc && donusDeger.objeler.Count == 0)                donusDeger.sonuc.bilgiStr = TasinirMalResI.TMM029;            dr.Close();            ve.VeriErisimKapat();            ve2.VeriErisimKapat();            return donusDeger;        }        /// <summary>        /// Verilen sayım tutanağı formunun detay bilgilerini döndüren yordam        /// </summary>        /// <param name="veriErisim">Veri tabanı bağlantı nesnesi</param>        /// <param name="kullanan">İşlemi yapan kullanıcıya ait bilgileri tutan nesne</param>        /// <param name="sf">Sayım tutanağı formunun kriter bilgilerini tutan nesne</param>        /// <param name="kayitBilgiEkle">Kayıtlara göre miktar bilgilerinin istenip istenmediği bilgisi</param>        /// <returns>Hata varsa ObjectArray içindeki Sonuc yapısında hata döndürülür, yoksa TNSCollection yapısında sayım tutanağı formuna ait detay bilgileri listesi döndürülür.</returns>        private static ObjectArray DetayListele(VeriErisim veriErisim, Kullanici kullanan, SayimForm sf, bool kayitBilgiEkle)        {            ObjectArray donusDeger = new ObjectArray();            VeriErisim ve = VeriErisim.VeriErisimBul(veriErisim, "BaglantiSatiriTMM", TNS.KYM.Arac.KimlikBul(kullanan));            //VeriErisim ve2 = VeriErisim.VeriErisimBul(null, "BaglantiSatiriTMM", TNS.KYM.Arac.KimlikBul(kullanan));            TABSayimDetay tabSD = new TABSayimDetay(ve);            //TABSayimDetay tabSD2 = new TABSayimDetay(ve2);            IDataReader dr = null;            try            {                dr = tabSD.Listele(sf);            }            catch (Exception e)            {                donusDeger.sonuc.islemSonuc = false;                donusDeger.sonuc.hataStr = e.Message;                dr.Close();                ve.VeriErisimKapat();                //ve2.VeriErisimKapat();                return donusDeger;            }            string muhasebeAd = sf.muhasebeAd;            string harcamaAd = sf.harcamaAd;            string ambarAd = sf.ambarAd;            if (!string.IsNullOrEmpty(sf.muhasebeKod) && string.IsNullOrEmpty(muhasebeAd))                muhasebeAd = TMMServis.UzayYaziDegerGetir("TASMUHASEBE", sf.muhasebeKod, true, "");            if (!string.IsNullOrEmpty(sf.harcamaKod) && string.IsNullOrEmpty(harcamaAd))                harcamaAd = TMMServis.UzayYaziDegerGetir("TASHARCAMABIRIM", sf.muhasebeKod + "-" + sf.harcamaKod.Replace(".", ""), true, "");            if (!string.IsNullOrEmpty(sf.ambarKod) && string.IsNullOrEmpty(ambarAd))                ambarAd = TMMServis.UzayYaziDegerGetir("TASAMBAR", sf.muhasebeKod + "-" + sf.harcamaKod.Replace(".", "") + "-" + sf.ambarKod, true, "");            System.Collections.Hashtable isimler = new System.Collections.Hashtable();            while (dr.Read())            {                SayimDetay gelen = new SayimDetay();                gelen.yil = VeriErisim.DegerAl(dr, 0, 0);                gelen.muhasebeKod = VeriErisim.DegerAl(dr, 1, string.Empty);                if (!string.IsNullOrEmpty(muhasebeAd))                    gelen.muhasebeAd = muhasebeAd;                else                    gelen.muhasebeAd = Genel.AdGetir(isimler, gelen.muhasebeKod, "TASMUHASEBE");                gelen.harcamaKod = VeriErisim.DegerAl(dr, 2, string.Empty);                gelen.harcamaKod = OrtakFonksiyonlar.KodNoktaKoy(Genel.KodYapiDondur(false), gelen.harcamaKod);                if (!string.IsNullOrEmpty(harcamaAd))                    gelen.harcamaAd = harcamaAd;                else                    gelen.harcamaAd = Genel.AdGetir(isimler, gelen.muhasebeKod + "-" + gelen.harcamaKod, "TASHARCAMABIRIM");                gelen.ambarKod = VeriErisim.DegerAl(dr, 3, string.Empty);                if (!string.IsNullOrEmpty(ambarAd))                    gelen.ambarAd = ambarAd;                else                    gelen.ambarAd = Genel.AdGetir(isimler, gelen.muhasebeKod + "-" + gelen.harcamaKod + "-" + gelen.ambarKod, "TASAMBAR");                gelen.sayimNo = VeriErisim.DegerAl(dr, 4, string.Empty);                gelen.hesapPlanKod = VeriErisim.DegerAl(dr, 5, string.Empty);                gelen.hesapPlanKod = OrtakFonksiyonlar.KodNoktaKoy(Genel.KodYapiDondur(true), gelen.hesapPlanKod);                gelen.hesapPlanAd = VeriErisim.DegerAl(dr, 11, string.Empty);                gelen.ambarMiktar = VeriErisim.DegerAl(dr, 6, (decimal)0);                gelen.ortakMiktar = VeriErisim.DegerAl(dr, 7, (decimal)0);                gelen.aciklama = VeriErisim.DegerAl(dr, 8, string.Empty);                gelen.olcuBirimKod = VeriErisim.DegerAl(dr, 9, 0);                gelen.olcuBirimAd = VeriErisim.DegerAl(dr, 10, string.Empty);                donusDeger.objeler.Add(gelen);            }            dr.Close();            //ERDAL Performans sıkıntısı yüzünden tek seferde çekiliyor kayıtlı miktarlar            //AmbardakileriGetir yukarıdaki while da commentli yerlere karşılık geliyor            //*********************************            if (donusDeger.objeler.Count > 0)                sf.detay = donusDeger.objeler;            donusDeger = AmbardakileriGetir(ve, kullanan, sf, kayitBilgiEkle);            //*********************************            if (donusDeger.objeler.Count == 0)                donusDeger.sonuc.bilgiStr = TasinirMalResI.TMM029;            //Boş satırları siliyor            //*********************            for (int i = 0; i < donusDeger.objeler.Count; i++)            {                SayimDetay sd = (SayimDetay)donusDeger.objeler[i];                if (sd.ambarMiktar == 0 && sd.fazlaMiktar == 0 && sd.kayitAmbarMiktar == 0 && sd.kayitKisiMiktar == 0                    && sd.kayitOrtakMiktar == 0 && sd.noksanMiktar == 0 && sd.ortakMiktar == 0)                {                    donusDeger.objeler.RemoveAt(i);                    i--;                }            }            //*********************            ve.VeriErisimKapat();            //ve2.VeriErisimKapat();            return donusDeger;        }        /// <summary>        /// Verilen kriterlere uygun olan ambardaki tüketim malzemelerini,        /// demirbaşları ve zimmetli demirbaşları döndüren yordam        /// </summary>        /// <param name="veriErisim">Veri tabanı bağlantı nesnesi</param>        /// <param name="kullanan">İşlemi yapan kullanıcıya ait bilgileri tutan nesne</param>        /// <param name="sf">Sayım tutanağı kriter bilgilerini tutan nesne</param>        /// <param name="hepsi">False olursa sadece kişi zimmetleri, true olursa bütün bilgiler listelenir.</param>        /// <returns>Hata varsa ObjectArray içindeki Sonuc yapısında hata döndürülür, yoksa TNSCollection yapısında ambardaki malzemelerin detay bilgileri listesi döndürülür.</returns>        public static ObjectArray AmbardakileriGetir(VeriErisim veriErisim, Kullanici kullanan, SayimForm sf, bool hepsi)        {            ObjectArray donusDeger = new ObjectArray();            //ERDAL Serverdan çağrıldığında sf'nin içi dolu gönderiliyor            //Burda da kayıt miktarları ekleniyor            //Clienttan geldiğinde sadece kayıt miktarları döndürülüyor            if (sf.detay.Count > 0)                donusDeger.objeler = sf.detay;            VeriErisim ve = VeriErisim.VeriErisimBul(veriErisim, "BaglantiSatiriTMM", TNS.KYM.Arac.KimlikBul(kullanan));            TABSayimDetay tabSD = new TABSayimDetay(ve);            IDataReader dr = null;            try            {                //Sayım tutanağında ekran işlemleri için (rapor dışında)                //kayitKisiMiktar gerekli olduğu için                if (hepsi)                {                    //Ambarda bulunan tüketimleri getiriyor                    //ilki giriş için, diğeri çıkış için                    dr = tabSD.AmbardakileriGetirFromStok(sf, true);                    AmbardakileriGetirBilgileriTopla(dr, ref donusDeger.objeler, "Ambar", true);                    dr = tabSD.AmbardakileriGetirFromStok(sf, false);                    AmbardakileriGetirBilgileriTopla(dr, ref donusDeger.objeler, "Ambar", false);                    //Ambarda aktif olarak bulunan sicilleri getiriyor                    //ilki giriş için, diğeri çıkış için                    dr = tabSD.AmbardakileriGetirFromSicil(sf, true);                    AmbardakileriGetirBilgileriTopla(dr, ref donusDeger.objeler, "Ambar", true);                    dr = tabSD.AmbardakileriGetirFromSicil(sf, false);                    AmbardakileriGetirBilgileriTopla(dr, ref donusDeger.objeler, "Ambar", false);                    //Ortak alanda zimmetli olan sicilleri getiriyor                    //ilki çıkış için, diğeri giriş için                    dr = tabSD.AmbardakileriGetirFromZIF(sf, true, false);                    AmbardakileriGetirBilgileriTopla(dr, ref donusDeger.objeler, "Ortak", false);                    dr = tabSD.AmbardakileriGetirFromZIF(sf, true, true);                    AmbardakileriGetirBilgileriTopla(dr, ref donusDeger.objeler, "Ortak", true);                }                //Kişilerde zimmetli olan sicilleri getiriyor                //ilki çıkış için, diğeri giriş için                dr = tabSD.AmbardakileriGetirFromZIF(sf, false, false);                AmbardakileriGetirBilgileriTopla(dr, ref donusDeger.objeler, "Kişi", false);                dr = tabSD.AmbardakileriGetirFromZIF(sf, false, true);                AmbardakileriGetirBilgileriTopla(dr, ref donusDeger.objeler, "Kişi", true);                TMMRaporlar.DetaySirala(ref donusDeger.objeler);            }            catch (Exception e)            {                donusDeger.sonuc.islemSonuc = false;                donusDeger.sonuc.hataStr = e.Message;            }            if (donusDeger.sonuc.islemSonuc)            {                if (donusDeger.objeler.Count == 0)                    donusDeger.sonuc.bilgiStr = TasinirMalResI.TMM029;            }            ve.VeriErisimKapat();            return donusDeger;        }        /// <summary>        /// Parametre olarak verilen DataReader nesnesini dolaşarak ambardaki malzemelerin detay bilgilerini toplayan yordam        /// </summary>        /// <param name="dr">DataReader nesnesi</param>        /// <param name="objeler">Daha önce toplanan bilgileri tutan nesne listesi</param>        /// <param name="islemTur">"Ambar", "Ortak" ve "Kişi" değerlerinden biri olmalıdır.</param>        /// <param name="girisMi">İşlem türünün tipi giriş mi değil mi</param>        private static void AmbardakileriGetirBilgileriTopla(IDataReader dr, ref TNSCollection objeler, string islemTur, bool girisMi)        {            if (dr != null)//ht:dr null geldiği durumlar oluyor            {                string kodYapi = Genel.KodYapiDondur(true);                while (dr.Read())                {                    SayimDetay gelen = null;                    string hesapKod = VeriErisim.DegerAl(dr, 0, string.Empty);                    hesapKod = OrtakFonksiyonlar.KodNoktaKoy(kodYapi, hesapKod);                    foreach (SayimDetay sd in objeler)                    {                        if (hesapKod == sd.hesapPlanKod)                        {                            gelen = sd;                            break;                        }                    }                    if (gelen == null)                    {                        gelen = new SayimDetay();                        objeler.Add(gelen);                    }                    gelen.hesapPlanKod = hesapKod;                    gelen.hesapPlanAd = VeriErisim.DegerAl(dr, 1, string.Empty);                    gelen.olcuBirimAd = VeriErisim.DegerAl(dr, 2, string.Empty);                    decimal miktar = VeriErisim.DegerAl(dr, 3, (decimal)0);                    if (islemTur == "Ambar")                    {                        if (girisMi)                            gelen.kayitAmbarMiktar += miktar;                        else                            gelen.kayitAmbarMiktar -= miktar;                    }                    else if (islemTur == "Ortak")                    {                        if (girisMi)                            gelen.kayitOrtakMiktar -= miktar;                        else                            gelen.kayitOrtakMiktar += miktar;                    }                    else                    {                        if (girisMi)                            gelen.kayitKisiMiktar -= miktar;                        else                            gelen.kayitKisiMiktar += miktar;                    }                    decimal kalan = (gelen.ambarMiktar + gelen.ortakMiktar) - (gelen.kayitAmbarMiktar + gelen.kayitOrtakMiktar);                    if (kalan > 0)                    {                        gelen.fazlaMiktar = kalan;                        gelen.noksanMiktar = 0;                    }                    else if (kalan < 0)                    {                        gelen.fazlaMiktar = 0;                        gelen.noksanMiktar = kalan * -1;                    }                    else                    {                        gelen.fazlaMiktar = 0;                        gelen.noksanMiktar = 0;                    }                }                dr.Close();            }        }    }}